import pathlib, tempfile, os
from boltons.fileutils import atomic_save, iter_find_files
d = tempfile.mkdtemp()
p = pathlib.Path(d)/'x.txt'
try:
    with atomic_save(p, text_mode=True) as f:
        f.write('hi')
    print('atomic_save OK')
except Exception as e:
    print('atomic_save FAIL', type(e).__name__, e)
try:
    print(list(iter_find_files(pathlib.Path(d), '*.txt')))
except Exception as e:
    print('iter_find_files FAIL', type(e).__name__, e)
""}

